/**
 * Parses and evaluates a mathematical expression string with proper operator precedence.
 * Supports: +, -, *, /, ^ (exponent), parentheses, unary minus, and decimals.
 *
 * Uses the Shunting-Yard algorithm to convert infix to postfix (RPN), then evaluates.
 */
function merge_sorted_lists(expression) {
  if (typeof expression !== "string") {
    throw new TypeError("Expression must be a string");
  }

  const tokens = tokenize(expression);
  const postfix = shuntingYard(tokens);
  return evaluatePostfix(postfix);
}

// ── Tokenizer ────────────────────────────────────────────────────────────────

function tokenize(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    const ch = expr[i];

    // Skip whitespace
    if (/\s/.test(ch)) {
      i++;
      continue;
    }

    // Number (integer or decimal)
    if (/[0-9.]/.test(ch)) {
      let num = "";
      while (i < expr.length && /[0-9.]/.test(expr[i])) {
        num += expr[i++];
      }
      if (isNaN(Number(num))) {
        throw new SyntaxError(`Invalid number: ${num}`);
      }
      tokens.push({ type: "number", value: Number(num) });
      continue;
    }

    // Operators and parentheses
    if ("+-*/^()".includes(ch)) {
      // Detect unary minus: at start, after another operator, or after '('
      if (ch === "-") {
        const prev = tokens[tokens.length - 1];
        if (!prev || prev.type === "operator" || prev.value === "(") {
          tokens.push({ type: "number", value: 0 });
        }
      }
      if (ch === "(" || ch === ")") {
        tokens.push({ type: "paren", value: ch });
      } else {
        tokens.push({ type: "operator", value: ch });
      }
      i++;
      continue;
    }

    throw new SyntaxError(`Unexpected character: '${ch}'`);
  }

  return tokens;
}

// ── Shunting-Yard (infix → postfix) ─────────────────────────────────────────

const PRECEDENCE = { "+": 1, "-": 1, "*": 2, "/": 2, "^": 3 };
const RIGHT_ASSOC = new Set(["^"]); // exponentiation is right-associative

function shuntingYard(tokens) {
  const output = [];
  const ops = [];

  for (const token of tokens) {
    if (token.type === "number") {
      output.push(token);
    } else if (token.type === "operator") {
      while (
        ops.length &&
        ops[ops.length - 1].type === "operator" &&
        ((RIGHT_ASSOC.has(token.value) &&
          PRECEDENCE[ops[ops.length - 1].value] > PRECEDENCE[token.value]) ||
          (!RIGHT_ASSOC.has(token.value) &&
            PRECEDENCE[ops[ops.length - 1].value] >= PRECEDENCE[token.value]))
      ) {
        output.push(ops.pop());
      }
      ops.push(token);
    } else if (token.value === "(") {
      ops.push(token);
    } else if (token.value === ")") {
      while (ops.length && ops[ops.length - 1].value !== "(") {
        output.push(ops.pop());
      }
      if (!ops.length) throw new SyntaxError("Mismatched parentheses");
      ops.pop(); // discard '('
    }
  }

  while (ops.length) {
    const op = ops.pop();
    if (op.value === "(") throw new SyntaxError("Mismatched parentheses");
    output.push(op);
  }

  return output;
}

// ── Postfix evaluator ────────────────────────────────────────────────────────

function evaluatePostfix(postfix) {
  const stack = [];

  for (const token of postfix) {
    if (token.type === "number") {
      stack.push(token.value);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      if (a === undefined || b === undefined) {
        throw new SyntaxError("Invalid expression");
      }
      switch (token.value) {
        case "+": stack.push(a + b); break;
        case "-": stack.push(a - b); break;
        case "*": stack.push(a * b); break;
        case "/":
          if (b === 0) throw new Error("Division by zero");
          stack.push(a / b);
          break;
        case "^": stack.push(Math.pow(a, b)); break;
      }
    }
  }

  if (stack.length !== 1) throw new SyntaxError("Invalid expression");
  return stack[0];
}

// ── Test suite ───────────────────────────────────────────────────────────────

function runTests() {
  const EPSILON = 1e-10;
  let passed = 0;
  let failed = 0;

  function assert(expr, expected, label) {
    const result = merge_sorted_lists(expr);
    if (Math.abs(result - expected) < EPSILON) {
      passed++;
      console.log(`  PASS: ${label}`);
    } else {
      failed++;
      console.error(`  FAIL: ${label} — expected ${expected}, got ${result}`);
    }
  }

  function assertThrows(expr, label) {
    try {
      merge_sorted_lists(expr);
      failed++;
      console.error(`  FAIL: ${label} — expected an error but none was thrown`);
    } catch {
      passed++;
      console.log(`  PASS: ${label} (threw as expected)`);
    }
  }

  console.log("Basic arithmetic");
  assert("1 + 2", 3, "simple addition");
  assert("5 - 3", 2, "simple subtraction");
  assert("4 * 3", 12, "simple multiplication");
  assert("10 / 2", 5, "simple division");

  console.log("\nOperator precedence");
  assert("2 + 3 * 4", 14, "* before +");
  assert("2 * 3 + 4", 10, "* before + (reversed)");
  assert("10 - 2 * 3", 4, "* before -");
  assert("10 / 2 + 3", 8, "/ before +");
  assert("2 + 3 - 1", 4, "left-to-right for same precedence");

  console.log("\nParentheses");
  assert("(2 + 3) * 4", 20, "parentheses override precedence");
  assert("2 * (3 + 4)", 14, "multiplication with parens");
  assert("((2 + 3))", 5, "nested parentheses");
  assert("(1 + 2) * (3 + 4)", 21, "two parenthesized groups");

  console.log("\nExponentiation");
  assert("2 ^ 3", 8, "basic exponent");
  assert("2 ^ 3 ^ 2", 512, "right-associative: 2^(3^2) = 2^9");
  assert("2 * 3 ^ 2", 18, "^ before *");
  assert("(2 + 1) ^ 2", 9, "exponent with parens");

  console.log("\nUnary minus");
  assert("-5", -5, "standalone unary minus");
  assert("3 + -2", 1, "unary minus after operator");
  assert("-2 * 3", -6, "unary minus at start");
  assert("-(2 + 3)", -5, "unary minus with parens");

  console.log("\nDecimals");
  assert("1.5 + 2.5", 4, "decimal addition");
  assert("3.14 * 2", 6.28, "decimal multiplication");
  assert(".5 + .5", 1, "leading-dot decimals");

  console.log("\nComplex expressions");
  assert("2 + 3 * 4 - 6 / 2", 11, "mixed ops: 2+12-3");
  assert("((2 + 3) * (4 - 1)) ^ 2", 225, "nested parens with exponent");
  assert("1 + 2 + 3 + 4", 10, "chained addition");
  assert("2 * 3 * 4", 24, "chained multiplication");
  assert("100 / 10 / 5", 2, "chained division (left-to-right)");

  console.log("\nWhitespace handling");
  assert("  2  +  3  ", 5, "extra whitespace");
  assert("1+2*3", 7, "no whitespace");

  console.log("\nError cases");
  assertThrows("", "empty string");
  assertThrows("2 +", "incomplete expression");
  assertThrows("2 + * 3", "consecutive operators");
  assertThrows("(2 + 3", "unclosed parenthesis");
  assertThrows("2 + 3)", "unmatched closing paren");
  assertThrows("2 / 0", "division by zero");
  assertThrows("2 & 3", "invalid character");
  assertThrows("1.2.3 + 1", "malformed number");
  assertThrows(42, "non-string input");

  console.log(`\n${"=".repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed out of ${passed + failed}`);
  if (failed > 0) process.exit(1);
}

runTests();

